// analyzer/functionTransform.ts:31
pub fn apply_function_transform(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    function_type: P<Type>,
    result: &FunctionResult,
) -> FunctionResult {
    if is_function(function_type) {
        let function_type = FunctionType(function_type);
        let full_name = function_type.d().shared.get().full_name;
        if full_name == "functools.total_ordering" {
            return apply_total_ordering_transform(evaluator, error_node, arg_list, result);
        }

        let struct_unpack_kind = get_struct_unpack_kind(&full_name);
        if let Some(struct_unpack_kind) = struct_unpack_kind {
            return apply_struct_unpack_transform(
                evaluator,
                error_node,
                arg_list,
                result,
                struct_unpack_kind,
            );
        }
    }

    // By default, return the result unmodified.
    result.clone()
}

// analyzer/functionTransform.ts:53
pub(crate) fn apply_total_ordering_transform(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    result: &FunctionResult,
) -> FunctionResult {
    if arg_list.len() != 1 {
        return result.clone();
    }

    // This function is meant to apply to a concrete instantiable class.
    let class_type = arg_list[0]
        .type_result()
        .map(|type_result| type_result.type_.get());
    let Some(class_type) = class_type else {
        return result.clone();
    };
    if !is_instantiable_class(class_type)
        || ClassType(class_type)
            .d()
            .priv_
            .borrow()
            .include_subclasses
            .unwrap_or(false)
    {
        return result.clone();
    }
    let class_type = ClassType(class_type);

    let ordering_methods = ["__lt__", "__le__", "__gt__", "__ge__"];
    let instance_type = ClassType::clone_as_instance(class_type, true);

    // Verify that the class has at least one of the required functions.
    let mut first_member_found: Option<ClassMember> = None;
    let missing_methods: Vec<&str> = ordering_methods
        .iter()
        .copied()
        .filter(|method_name| {
            let member_info = look_up_object_member(
                instance_type,
                method_name,
                MemberAccessFlags::SkipInstanceMembers,
                None,
            );
            if member_info.is_some() && first_member_found.is_none() {
                first_member_found = member_info.clone();
            }
            member_info.is_none()
        })
        .collect();

    let Some(first_member_found) = first_member_found else {
        evaluator.add_diagnostic(
            DiagnosticRule::reportGeneralTypeIssues,
            &LocMessage::total_ordering_missing_method(),
            error_node,
            None,
        );
        return result.clone();
    };

    // Determine what type to use for the parameter corresponding to
    // the second operand. This will be taken from the existing method.
    let mut operand_type: Option<P<Type>> = None;

    let first_member_type = evaluator.get_type_of_member(&first_member_found);
    if is_function(first_member_type) {
        let first_member_function = FunctionType(first_member_type);
        let second_param_declared = {
            let parameters = first_member_function.d().shared.get().parameters.get();
            let parameters = parameters.borrow();
            parameters.len() >= 2 && FunctionParam::is_type_declared(&parameters[1])
        };
        if second_param_declared {
            operand_type = Some(FunctionType::get_param_type(first_member_function, 1));
        }
    }

    // If there was no provided operand type, fall back to object.
    let operand_type = match operand_type {
        Some(operand_type) => operand_type,
        None => {
            let object_type = evaluator.get_built_in_object(error_node, jsrt::atom!("object"), None);
            if !is_class_instance(object_type) {
                return result.clone();
            }
            object_type
        }
    };

    let bool_type = evaluator.get_built_in_object(error_node, jsrt::atom!("bool"), None);
    if !is_class_instance(bool_type) {
        return result.clone();
    }

    let self_param = FunctionParam::create(
        ParamCategory::Simple,
        synthesize_type_var_for_self_cls(class_type, /* isClsParam */ false).0,
        FunctionParamFlags::TypeDeclared,
        Some("self"),
        None,
        None,
    );

    let obj_param = FunctionParam::create(
        ParamCategory::Simple,
        operand_type,
        FunctionParamFlags::TypeDeclared,
        Some("__value"),
        None,
        None,
    );

    // Add the missing members to the class's symbol table.
    for method_name in missing_methods {
        let method_to_add =
            FunctionType::create_synthesized_instance(method_name, FunctionTypeFlags::None);
        FunctionType::add_param(method_to_add, &self_param);
        FunctionType::add_param(method_to_add, &obj_param);
        method_to_add
            .d()
            .shared
            .get()
            .declared_return_type
            .set(Some(bool_type));

        ClassType::get_symbol_table(class_type).set(
            method_name,
            Symbol::create_with_type(SymbolFlags::ClassMember, method_to_add.0, None),
        );
    }

    result.clone()
}

// analyzer/functionTransform.ts:157
pub(crate) fn get_struct_unpack_kind(full_name: &str) -> Option<StructUnpackKind> {
    match full_name {
        "_struct.unpack" | "_struct.unpack_from" => Some(StructUnpackKind::Tuple),

        "_struct.iter_unpack" => Some(StructUnpackKind::Iterator),

        _ => None,
    }
}

// analyzer/functionTransform.ts:173
pub(crate) const MAX_STRUCT_UNPACK_ELEMENT_COUNT: u32 = 256;

// analyzer/functionTransform.ts:175
pub(crate) fn apply_struct_unpack_transform(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    result: &FunctionResult,
    kind: StructUnpackKind,
) -> FunctionResult {
    // The format string is always the first positional argument.
    if arg_list.is_empty() {
        return result.clone();
    }

    let format_type = evaluator
        .get_type_of_arg(&arg_list[0], /* inferenceContext */ None)
        .type_
        .get();
    if !is_class_instance(format_type) {
        return result.clone();
    }
    let format_class = ClassType(format_type);

    // The format must be a `str` or `bytes` literal. Both store their value
    // as a string in `literalValue`.
    if !ClassType::is_built_in(
        format_class,
        Some(&[jsrt::atom!("str"), jsrt::atom!("bytes")]),
    ) {
        return result.clone();
    }

    let format_value = format_class.d().priv_.borrow().literal_value.clone();
    let Some(LiteralValue::String(format_value)) = format_value else {
        return result.clone();
    };

    let element_kinds = parse_struct_format(&format_value.to_string_lossy());
    let Some(element_kinds) =
        element_kinds.filter(|kinds| kinds.len() as u32 <= MAX_STRUCT_UNPACK_ELEMENT_COUNT)
    else {
        return result.clone();
    };

    let mut element_type_cache: JsMap<StructElementType, P<Type>> = JsMap::default();
    let mut get_element_type = |element_kind: StructElementType| -> Option<P<Type>> {
        let mut element_type = element_type_cache.get(&element_kind).copied();
        if element_type.is_none() {
            let built_in_type =
                evaluator.get_built_in_object(error_node, element_kind.as_str(), None);
            if !is_class_instance(built_in_type) {
                return None;
            }
            element_type = Some(built_in_type);
            element_type_cache.insert(element_kind, built_in_type);
        }
        element_type
    };

    let mut tuple_args: Vec<TupleTypeArg> = Vec::new();
    for element_kind in element_kinds {
        let Some(element_type) = get_element_type(element_kind) else {
            return result.clone();
        };
        tuple_args.push(TupleTypeArg {
            type_: element_type,
            is_unbounded: false,
            is_optional: None,
        });
    }

    let tuple_type = make_tuple_object(evaluator, &tuple_args, false);

    if kind == StructUnpackKind::Tuple {
        return FunctionResult {
            return_type: tuple_type,
            ..result.clone()
        };
    }

    // iter_unpack returns an Iterator of the synthesized tuple type.
    let iterator_type = evaluator.get_typing_type(error_node, "Iterator");
    let Some(iterator_type) =
        iterator_type.filter(|&iterator_type| is_instantiable_class(iterator_type))
    else {
        return result.clone();
    };

    let iterator_instance = ClassType::clone_as_instance(
        ClassType::specialize(
            ClassType(iterator_type),
            Some(&[tuple_type]),
            None,
            false,
            None,
            None,
        ),
        true,
    );
    FunctionResult {
        return_type: iterator_instance.0,
        ..result.clone()
    }
}

// analyzer/functionTransform.ts:250
pub(crate) fn parse_struct_format(format: &str) -> Option<Vec<StructElementType>> {
    // The string is read as JavaScript does, one UTF-16 code unit at a time.
    let format: Vec<u16> = format.encode_utf16().collect();
    let unit_text = |unit: u16| String::from_utf16_lossy(&[unit]);
    let is_digit = |unit: u16| (u16::from(b'0')..=u16::from(b'9')).contains(&unit);

    let mut elements: Vec<StructElementType> = Vec::new();
    let mut index = 0;

    // An optional leading byte-order/size/alignment character. The 'n', 'N',
    // and 'P' codes are only valid in native mode (no prefix or '@'); under an
    // explicit byte-order prefix ('=', '<', '>', '!') they raise struct.error.
    let mut is_native_mode = true;
    if index < format.len() && "@=<>!".encode_utf16().any(|unit| unit == format[index]) {
        is_native_mode = format[index] == u16::from(b'@');
        index += 1;
    }

    while index < format.len() {
        let ch = format[index];

        // Whitespace between format codes is ignored.
        if [b' ', b'\t', b'\n', b'\r', 0x0c, 0x0b]
            .iter()
            .any(|&w| u16::from(w) == ch)
        {
            index += 1;
            continue;
        }

        // An optional repeat count precedes the format code.
        let mut count: f64 = -1.0;
        if is_digit(ch) {
            count = 0.0;
            while index < format.len() && is_digit(format[index]) {
                count = count * 10.0 + f64::from(format[index] - 0x30);
                index += 1;

                // Guard against pathologically large counts. This bounds the
                // accumulator itself; the produced element count is bounded
                // separately below so byte-length codes ('s'/'p') aren't
                // rejected for large counts.
                if count > 9007199254740991.0 {
                    return None;
                }
            }

            // A count must be followed by a format code.
            if index >= format.len() {
                return None;
            }
        }

        let code = unit_text(format[index]);
        index += 1;

        let element_kind = get_struct_element_type(&code, is_native_mode)?;

        if code == "s" || code == "p" {
            // For 's' and 'p', the count is the byte length of a single value,
            // so it always produces exactly one element regardless of count.
            elements.push(StructElementType::Bytes);
        } else if element_kind == "pad" {
            // Pad bytes ('x') produce no elements.
        } else {
            let element_kind = match element_kind.as_str() {
                "int" => StructElementType::Int,
                "float" => StructElementType::Float,
                "bool" => StructElementType::Bool,
                "bytes" => StructElementType::Bytes,
                _ => unreachable!("getStructElementType returns an element type or 'pad'"),
            };
            let repeat = if count < 0.0 { 1.0 } else { count };
            let mut i = 0.0;
            while i < repeat {
                elements.push(element_kind);

                // Bound the produced element count to avoid performance issues
                // with very large repeat counts.
                if elements.len() as u32 > MAX_STRUCT_UNPACK_ELEMENT_COUNT {
                    return None;
                }
                i += 1.0;
            }
        }
    }

    Some(elements)
}

// analyzer/functionTransform.ts:326
pub(crate) fn get_struct_element_type(code: &str, is_native_mode: bool) -> Option<String> {
    let element_type = match code {
        "x" => "pad",

        "c" | "s" | "p" => "bytes",

        "b" | "B" | "h" | "H" | "i" | "I" | "l" | "L" | "q" | "Q" => "int",

        // These codes are only available in native mode (no prefix or '@').
        // Under an explicit byte-order prefix they are invalid, so fall back
        // to the declared return type rather than synthesizing 'int'.
        "n" | "N" | "P" => {
            if is_native_mode {
                "int"
            } else {
                return None;
            }
        }

        "?" => "bool",

        "e" | "f" | "d" => "float",

        _ => return None,
    };
    Some(element_type.to_string())
}

