#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum StructUnpackKind {
    Tuple,
    Iterator,
}

impl StructUnpackKind {
    pub fn as_str(self) -> &'static str {
        match self {
            StructUnpackKind::Tuple => "tuple",
            StructUnpackKind::Iterator => "iterator",
        }
    }
}

