pub enum StructElementType {
    Int,
    Float,
    Bool,
    Bytes,
}

impl StructElementType {
    pub fn as_str(self) -> &'static str {
        match self {
            StructElementType::Int => "int",
            StructElementType::Float => "float",
            StructElementType::Bool => "bool",
            StructElementType::Bytes => "bytes",
        }
    }
}
